package dev.cardadvisor.auth;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;import org.springframework.mail.javamail.JavaMailSenderImpl;import javax.net.ssl.*;import java.security.*;import java.nio.file.*;import java.net.*;import java.io.*;import java.util.*;import java.util.concurrent.*;import static org.junit.jupiter.api.Assertions.*;
class SmtpTlsContractTest{
 @TempDir Path temp;
 @Test void implicitTlsWireAndVerificationCodeUseOnlyLocalMailbox()throws Exception{
  String password=UUID.randomUUID().toString();Path store=temp.resolve("smtp-test.p12");var builder=new ProcessBuilder(Path.of(System.getProperty("java.home"),"bin",System.getProperty("os.name").startsWith("Windows")?"keytool.exe":"keytool").toString(),"-genkeypair","-alias","smtp","-keyalg","RSA","-keysize","2048","-validity","1","-dname","CN=localhost","-ext","SAN=dns:localhost,ip:127.0.0.1","-storetype","PKCS12","-keystore",store.toString(),"-storepass:env","SYNTHETIC_TLS_PASSWORD").redirectErrorStream(true);builder.environment().put("SYNTHETIC_TLS_PASSWORD",password);var process=builder.start();process.getInputStream().transferTo(OutputStream.nullOutputStream());assertTrue(process.waitFor(20,TimeUnit.SECONDS));assertEquals(0,process.exitValue());
  var ks=KeyStore.getInstance("PKCS12");try(var in=Files.newInputStream(store)){ks.load(in,password.toCharArray());}var km=KeyManagerFactory.getInstance(KeyManagerFactory.getDefaultAlgorithm());km.init(ks,password.toCharArray());var tm=TrustManagerFactory.getInstance(TrustManagerFactory.getDefaultAlgorithm());tm.init(ks);var tls=SSLContext.getInstance("TLS");tls.init(km.getKeyManagers(),tm.getTrustManagers(),null);
  try(var server=(SSLServerSocket)tls.getServerSocketFactory().createServerSocket(0,1,InetAddress.getLoopbackAddress())){
   server.setSoTimeout(10000);var received=new CompletableFuture<String>();var executor=Executors.newSingleThreadExecutor();
   executor.submit(()->{try(var socket=server.accept()){socket.setSoTimeout(10000);var in=new BufferedReader(new InputStreamReader(socket.getInputStream(),java.nio.charset.StandardCharsets.UTF_8));var out=new PrintWriter(socket.getOutputStream(),true);out.print("220 localhost synthetic\r\n");out.flush();String line;boolean data=false;var body=new StringBuilder();while((line=in.readLine())!=null){if(data){if(line.equals(".")){data=false;out.print("250 stored\r\n");received.complete(body.toString());}else body.append(line).append('\n');}else if(line.startsWith("EHLO"))out.print("250 localhost\r\n");else if(line.equals("DATA")){data=true;out.print("354 continue\r\n");}else if(line.equals("QUIT")){out.print("221 bye\r\n");out.flush();break;}else out.print("250 ok\r\n");out.flush();}}catch(Exception e){received.completeExceptionally(new IllegalStateException("SYNTHETIC_SMTP_FAILED"));}});
   try{var sender=new JavaMailSenderImpl();sender.setHost("localhost");sender.setPort(server.getLocalPort());sender.setDefaultEncoding("UTF-8");var props=sender.getJavaMailProperties();props.put("mail.smtp.ssl.enable","true");props.put("mail.smtp.ssl.checkserveridentity","true");props.put("mail.smtp.ssl.socketFactory",tls.getSocketFactory());props.put("mail.smtp.timeout","5000");new SmtpAccountMail(sender,"sender@example.test").send("receiver@example.test","VERIFY_EMAIL","SYNTHETIC-ONLY-CODE");String body=received.get(10,TimeUnit.SECONDS);assertTrue(body.contains("receiver@example.test"));var message=new jakarta.mail.internet.MimeMessage(jakarta.mail.Session.getInstance(new Properties()),new ByteArrayInputStream(body.getBytes(java.nio.charset.StandardCharsets.UTF_8)));assertTrue(message.getContent().toString().contains("SYNTHETIC-ONLY-CODE"));assertFalse(body.contains(password));}finally{executor.shutdownNow();}
  }
 }
 @Test void startTlsIsRequiredAndDisabledConfigurationCannotSend()throws Exception{
  assertFalse(new SmtpAccountMail("").ready());assertThrows(dev.cardadvisor.api.ApiError.class,()->new SmtpAccountMail("").send("receiver@example.test","RESET_PASSWORD","synthetic"));
  Path cfg=temp.resolve("mail.properties");Files.writeString(cfg,"enabled=true\nhost=localhost\nport=587\nfrom=sender@example.test\nusername=synthetic\npassword=synthetic\n");var gateway=new SmtpAccountMail(cfg.toString());var field=SmtpAccountMail.class.getDeclaredField("sender");field.setAccessible(true);var sender=(JavaMailSenderImpl)field.get(gateway);assertEquals("true",sender.getJavaMailProperties().get("mail.smtp.starttls.required"));assertEquals("true",sender.getJavaMailProperties().get("mail.smtp.ssl.checkserveridentity"));assertEquals("false",sender.getJavaMailProperties().get("mail.debug"));
 }
}
